            ).then(() => downloadPath),
        )
        .then((downloadPath) => {
            RNFetchBlob.fs.unlink(downloadPath);
            FileUtils.showSuccessAlert();
        })
        .catch(() => {
            if (!onDownloadFailed) {
                FileUtils.showGeneralErrorAlert();
            }
            onDownloadFailed?.();
